import csv
import io

def run(inputs: dict) -> dict:
    # 1. Извлекаем денежные средства
    metrics = inputs.get("ExtractedMetric", [])
    cash = {}
    for m in metrics:
        if m.get("concept") != "Денежные средства и денежные эквиваленты":
            continue
        sf = m.get("scalar_fact")
        if not sf:
            continue
        period = sf.get("period_ref")
        unit = sf.get("unit")
        value = sf.get("value")
        if period in ("FY 2024", "FY 2025") and unit == "млн. руб.":
            cash[period] = value

    if "FY 2024" not in cash or "FY 2025" not in cash:
        raise ValueError("Не найдены денежные средства за FY 2024 и FY 2025 в млн руб.")

    # 2. Парсим CSV с ценами Brent
    dyn_list = inputs.get("dyn:brent_yearly_prices", [])
    if not dyn_list:
        raise ValueError("Нет скачанного CSV с ценами Brent")
    csv_text = dyn_list[0]["payload"]["text"]

    reader = csv.DictReader(io.StringIO(csv_text))
    brent = {}
    for row in reader:
        year = row.get("year")
        price = row.get("price")
        if year in ("2024", "2025") and price:
            brent[int(year)] = float(price)

    if 2024 not in brent or 2025 not in brent:
        raise ValueError("Не найдены цены Brent за 2024 и 2025 в CSV")

    # 3. Расчёт изменений
    cash_2024 = cash["FY 2024"]
    cash_2025 = cash["FY 2025"]
    brent_2024 = brent[2024]
    brent_2025 = brent[2025]

    if cash_2024 == 0:
        raise ValueError("Денежные средства за FY 2024 равны нулю, расчёт изменения невозможен")
    if brent_2024 == 0:
        raise ValueError("Цена Brent за 2024 равна нулю, расчёт изменения невозможен")

    cash_change_pct = (cash_2025 - cash_2024) / cash_2024 * 100
    brent_change_pct = (brent_2025 - brent_2024) / brent_2024 * 100

    return {
        "cash_2024_mln_rub": cash_2024,
        "cash_2025_mln_rub": cash_2025,
        "brent_2024_usd_per_bbl": brent_2024,
        "brent_2025_usd_per_bbl": brent_2025,
        "cash_change_pct": cash_change_pct,
        "brent_change_pct": brent_change_pct,
    }

